using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// HttpClient is injected via constructor DI — registered as a typed client in Program.cs.
/// </summary>
[McpServerToolType]
public class JsonPlaceholderTools(HttpClient httpClient)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get a post by its ID from the JSONPlaceholder API.")]
    public async Task<string> GetPost(
        [Description("The numeric ID of the post (1-100)")] int postId,
        CancellationToken cancellationToken = default)
    {
        var response = await httpClient.GetAsync($"/posts/{postId}", cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool, Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts by this user ID. Omit to list all posts.")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);

        var summary = doc.RootElement.EnumerateArray()
            .Select(p => new { id = p.GetProperty("id").GetInt32(), title = p.GetProperty("title").GetString() });

        return JsonSerializer.Serialize(summary, JsonOptions);
    }

    [McpServerTool, Description("Create a new post (simulated — JSONPlaceholder returns the created object but does not persist it).")]
    public async Task<string> CreatePost(
        [Description("User ID of the post author")] int userId,
        [Description("Title of the post")] string title,
        [Description("Body content of the post")] string body,
        CancellationToken cancellationToken = default)
    {
        var payload = new { userId, title, body };
        var response = await httpClient.PostAsJsonAsync("/posts", payload, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("Get all comments for a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to retrieve comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        var response = await httpClient.GetAsync($"/posts/{postId}/comments", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

